// Cache-aside with write-invalidation (Node.js / ioredis)
import { Redis } from 'ioredis';
const redis = new Redis(process.env.REDIS_URL);

const CACHE_TTL = 300; // seconds

// READ — lazy population
async function getProduct(id) {
  const key = `product:${id}`;
  const hit = await redis.get(key);
  if (hit) return JSON.parse(hit); // cache hit: ~0.5ms

  const row = await db.query(
    'SELECT * FROM products WHERE id = $1', [id]
  );
  if (row) await redis.setex(key, CACHE_TTL, JSON.stringify(row));
  return row; // cache miss: ~20ms, populates cache
}

// WRITE — invalidate stale entry
async function updateProductPrice(id, price) {
  await db.query(
    'UPDATE products SET price = $1 WHERE id = $2', [price, id]
  );
  await redis.del(`product:${id}`); // next read re-fetches fresh data
}

// CDN cache headers on Express response
app.get('/api/public/products', async (req, res) => {
  const products = await getProductList();
  res
    .set('Cache-Control', 'public, max-age=60, stale-while-revalidate=30')
    .json(products);
  // CDN caches 60s; serves stale for 30s while revalidating in background
});

// Caching strategy decision guide

// Cache-aside (lazy loading)
// Best for: read-heavy, tolerates brief staleness, unpredictable access patterns
// Pro:  only caches accessed data — efficient memory usage
// Con:  first request after miss/expiry is slow (thundering herd risk)

// Write-through
// Best for: write + read symmetry, low write frequency, zero stale tolerance
// Pro:  cache always warm on writes
// Con:  every write pays cache + DB latency; pollutes cache with unread data

// Write-back
// Best for: write-heavy workloads where some loss is acceptable (analytics, counters)
// Pro:  writes return in <1ms
// Con:  data loss window if cache crashes before flush

// TTL guide (rough)
const TTL = {
  sessionTokens:     3600,      // 1 hour — security-sensitive
  productCatalog:    86400,     // 24 hours — rarely changes
  userProfile:       300,       // 5 min — changes occasionally
  searchResults:     60,        // 1 min — freshness matters
  realtimeCounters:  1,         // 1 sec — near-realtime
};

// CDN Cache-Control cheat sheet
// Versioned static files: Cache-Control: public, max-age=31536000, immutable
// Public API responses:   Cache-Control: public, max-age=60, stale-while-revalidate=30
// Personalized responses: Cache-Control: private, no-store
